/* Aetherbound field HUD overhaul */
@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Silkscreen:wght@400;700&display=swap');
:root{--ink:#e7f2f4;--muted:#91a7b0;--panel:rgba(15,23,42,.84);--line:rgba(148,185,197,.2);--cyan:#06b6d4;--gold:#eab308;--red:#fb7185;--purple:#a78bfa;--flame:#f97316;--hydro:#3b82f6;--gale:#10b981;--terra:#eab308}
body{background:#071019;font-family:'Silkscreen','DM Mono',monospace}
#app{height:100dvh;min-height:520px;grid-template-rows:42px minmax(0,1fr) 88px;background:#071019}
.topbar{height:42px;padding:0 20px;gap:22px;background:rgba(15,23,42,.74);backdrop-filter:blur(16px);border-bottom:1px solid rgba(103,232,249,.18);box-shadow:0 5px 24px #02061744}
.brand{min-width:auto;gap:9px}.brandmark{width:24px;height:24px;border-radius:6px;border-color:#06b6d4;box-shadow:0 0 16px #06b6d455;font-size:13px}.brandtitle{font:9px 'Press Start 2P',monospace;letter-spacing:0;color:#e6fbff}.brandtitle small{font:8px 'Silkscreen',monospace;letter-spacing:.08em;margin-top:3px;color:#67e8f9}.biome{font-size:11px;color:#c5d6e5}.top-spacer{flex:1}.resource{gap:6px;font-size:11px}.resource b{color:#67e8f9}.run-chip{padding:5px 10px;border-color:#06b6d455;color:#d4e5ef;background:#0f172a88;border-radius:4px;font-size:10px}
