function openModal(title,subtitle,items){$('modalTitle').textContent=title;$('modalSubtitle').textContent=subtitle;$('modalContent').innerHTML=items.map(x=>`<div class="modal-item"><h3>${x.icon||'✧'} ${x.name}</h3><p>${x.desc}</p>${x.button?`<button data-modal-action="${x.action}" data-class="${x.class||''}">${x.button}</button>`:''}</div>`).join('');$('modalWrap').classList.add('open');$('modalContent').querySelectorAll('[data-modal-action]').forEach(b=>b.onclick=()=>modalAction(b.dataset.modalAction,b.dataset.class))}
